CREATE OR REPLACE FUNCTION calc.add_attachment_selection(p_quote_id character varying, p_product_code character varying DEFAULT NULL::character varying, p_model_code character varying DEFAULT NULL::character varying, p_item_name character varying DEFAULT NULL::character varying, p_quantity numeric DEFAULT 1, p_width_mm integer DEFAULT NULL::integer, p_height_mm integer DEFAULT NULL::integer, p_depth_mm integer DEFAULT NULL::integer, p_variant character varying DEFAULT NULL::character varying, p_price_source character varying DEFAULT NULL::character varying, p_unit_price_override numeric DEFAULT NULL::numeric, p_notes text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
AS $function$
DECLARE
 v_price calc.attachment_price%ROWTYPE;
 v_selection_id BIGINT;
BEGIN
 IF p_quote_id IS NULL OR btrim(p_quote_id) = '' THEN
 RAISE EXCEPTION 'quote_id is required';
 END IF;
 IF p_model_code IS NULL AND p_item_name IS NULL THEN
 RAISE EXCEPTION 'model_code or item_name is required';
 END IF;
 IF p_quantity IS NULL OR p_quantity < 0 THEN
 RAISE EXCEPTION 'quantity must be non-negative';
 END IF;

 SELECT ap.*
 INTO v_price
 FROM calc.attachment_price ap
 WHERE ap.is_active = TRUE
 AND (p_model_code IS NULL OR ap.model_code = p_model_code OR ap.model_code IS NULL OR ap.model_code = '所有型号')
 AND (p_item_name IS NULL OR ap.item_name = p_item_name)
 AND (p_width_mm IS NULL OR ap.width_mm = p_width_mm)
 AND (p_height_mm IS NULL OR ap.height_mm = p_height_mm)
 AND (p_depth_mm IS NULL OR ap.depth_mm = p_depth_mm)
 AND (p_variant IS NULL OR ap.variant = p_variant OR ap.variant IS NULL)
 AND (p_price_source IS NULL OR ap.price_source = p_price_source)
 ORDER BY
 CASE WHEN ap.model_code = p_model_code THEN 0 ELSE 1 END,
 CASE WHEN ap.item_name = p_item_name THEN 0 ELSE 1 END,
 ap.attachment_price_id DESC
 LIMIT 1;

 IF NOT FOUND THEN
 RAISE EXCEPTION 'attachment price not found: model=%, item=%, variant=%, source=%',
 p_model_code, p_item_name, p_variant, p_price_source;
 END IF;

 INSERT INTO calc.attachment_selection (
 quote_id, product_code, model_code, attachment_price_id,
 item_name, variant, price_source, quantity, unit_price,
 price_text, cost_method, notes
 )
 VALUES (
 p_quote_id, p_product_code, v_price.model_code, v_price.attachment_price_id,
 v_price.item_name, v_price.variant, v_price.price_source, p_quantity,
 COALESCE(p_unit_price_override, v_price.price), v_price.price_text,
 'experience', p_notes
 )
 RETURNING attachment_selection_id INTO v_selection_id;

 RETURN v_selection_id;
END;
$function$

CREATE OR REPLACE FUNCTION calc.calculate_dual_quote(p_quote_id character varying, p_product_code character varying, p_model_code character varying, p_material_code character varying, p_width_mm numeric, p_height_mm numeric, p_depth_mm numeric, p_base_material_weight_kg numeric DEFAULT NULL::numeric, p_product_area_m2 numeric DEFAULT NULL::numeric, p_coating_type character varying DEFAULT '平光'::character varying, p_variant_code character varying DEFAULT NULL::character varying, p_quote_date date DEFAULT CURRENT_DATE)
 RETURNS TABLE(quote_id character varying, product_code character varying, model_code character varying, material_code character varying, formula_material_cost numeric, formula_auxiliary_cost numeric, formula_labor_cost numeric, formula_attachment_fee numeric, formula_product_area_m2 numeric, formula_spray_cost numeric, formula_management_fee numeric, formula_total_cost numeric, quick_rule_id bigint, quick_match_method character varying, quick_match_distance numeric, quick_material_cost numeric, quick_auxiliary_cost numeric, quick_labor_cost numeric, quick_attachment_fee numeric, quick_spray_cost numeric, quick_management_fee numeric, quick_total_cost numeric, difference_cost numeric, risk_flags jsonb)
 LANGUAGE plpgsql
AS $function$
DECLARE
 v_formula RECORD;
 v_quick RECORD;
 v_risks JSONB := '[]'::jsonb;
 v_product_code VARCHAR;
 v_quick_attachment NUMERIC := 0;
 v_quick_base NUMERIC;
 v_quick_total NUMERIC;
 v_difference NUMERIC;
BEGIN
 IF p_quote_id IS NULL OR btrim(p_quote_id) = '' THEN
 RAISE EXCEPTION 'quote_id is required';
 END IF;
 IF p_material_code NOT IN ('SECC','SUS304','SUS316') THEN
 RAISE EXCEPTION 'unsupported material_code: %', p_material_code;
 END IF;
 IF p_width_mm IS NULL OR p_height_mm IS NULL OR p_depth_mm IS NULL
 OR p_width_mm <= 0 OR p_height_mm <= 0 OR p_depth_mm <= 0 THEN
 RAISE EXCEPTION 'width, height and depth must be positive';
 END IF;

 v_product_code := CASE p_product_code
 WHEN 'JC' THEN 'JC_EXP'
 WHEN 'JQ' THEN 'JQ_EXP'
 WHEN U&'\8D85\5BBDJP' THEN 'JP_WIDE_EXP'
 WHEN U&'\8D85\5BBDJS' THEN 'JS_WIDE_EXP'
 WHEN U&'\64CD\4F5C\53F0' THEN 'OP_TABLE_EXP'
 ELSE p_product_code END;

 /* Formula quotation remains the existing DB-owned calculation. */
 SELECT * INTO v_formula
 FROM calc.calculate_quote_total(
 p_quote_id, v_product_code, COALESCE(p_model_code,''), p_material_code,
 p_width_mm, p_height_mm, p_depth_mm, p_base_material_weight_kg,
 p_product_area_m2, p_coating_type, p_variant_code, p_quote_date);

 IF v_formula.material_cost IS NULL THEN
 v_risks := v_risks || jsonb_build_array(jsonb_build_object(
 'code','formula_material_cost_missing','severity','blocker'));
 END IF;

 /* Quick quotation reads experience values only. */
 SELECT * INTO v_quick
 FROM calc.match_quick_quote(
 v_product_code, p_model_code, p_material_code,
 p_width_mm, p_height_mm, p_depth_mm, p_quote_date);

 IF NOT FOUND THEN
 v_risks := v_risks || jsonb_build_array(jsonb_build_object(
 'code','quick_quote_missing','severity','blocker',
 'message',U&'\5F85\8865\5145\7ECF\9A8C\503C'));
 v_quick_total := NULL;
 ELSE
 /* match_quick_quote returns the direct quick base in quick_total_cost.
 It intentionally does not expose formula-derived components. */
 v_quick_base := v_quick.quick_total_cost;
 v_quick_attachment := COALESCE(calc.get_attachment_fee(p_quote_id, v_product_code), 0);
 v_quick_total := v_quick_base + v_quick_attachment;
 END IF;

 IF v_formula.total_cost IS NOT NULL AND v_quick_total IS NOT NULL THEN
 v_difference := ROUND(v_quick_total - v_formula.total_cost, 2);
 END IF;

 /* A quote_id is the logical version key. Replace the previous snapshot
 before writing the new one; this also makes repeated smoke tests safe. */
 DELETE FROM calc.dual_quote_result
 WHERE calc.dual_quote_result.quote_id = $1;

 INSERT INTO calc.dual_quote_result(
 quote_id,product_code,model_code,material_code,
 input_width_mm,input_height_mm,input_depth_mm,quote_date,
 formula_material_cost,formula_auxiliary_cost,formula_labor_cost,
 formula_attachment_fee,formula_product_area_m2,formula_spray_cost,
 formula_management_fee,formula_total_cost,
 quick_rule_id,quick_match_method,quick_match_distance,
 quick_material_cost,quick_auxiliary_cost,quick_labor_cost,
 quick_attachment_fee,quick_spray_cost,quick_management_fee,quick_base_price,
 quick_total_cost,difference_cost,risk_flags,updated_at)
 VALUES(
 p_quote_id,v_product_code,p_model_code,p_material_code,
 p_width_mm,p_height_mm,p_depth_mm,p_quote_date,
 v_formula.material_cost,v_formula.auxiliary_cost,v_formula.labor_cost,
 v_formula.attachment_fee,v_formula.product_area_m2,v_formula.spray_cost,
 v_formula.management_fee,v_formula.total_cost,
 v_quick.quick_rule_id,v_quick.match_method,v_quick.dimension_distance,
 v_quick.quick_material_cost,v_quick.quick_auxiliary_cost,v_quick.quick_labor_cost,
 v_quick_attachment,v_quick.quick_spray_cost,v_quick.quick_management_fee,v_quick_base,
 v_quick_total,v_difference,v_risks,now());

 RETURN QUERY SELECT
 p_quote_id,v_product_code,p_model_code,p_material_code,
 v_formula.material_cost,v_formula.auxiliary_cost,v_formula.labor_cost,
 v_formula.attachment_fee,v_formula.product_area_m2,v_formula.spray_cost,
 v_formula.management_fee,v_formula.total_cost,
 v_quick.quick_rule_id,v_quick.match_method,v_quick.dimension_distance,
 v_quick.quick_material_cost,v_quick.quick_auxiliary_cost,v_quick.quick_labor_cost,
 v_quick_attachment,v_quick.quick_spray_cost,v_quick.quick_management_fee,
 v_quick_total,v_difference,v_risks;
END;
$function$

CREATE OR REPLACE FUNCTION calc.add_attachment_selection(p_quote_id character varying, p_product_code character varying DEFAULT NULL::character varying, p_model_code character varying DEFAULT NULL::character varying, p_item_name character varying DEFAULT NULL::character varying, p_quantity numeric DEFAULT 1, p_width_mm integer DEFAULT NULL::integer, p_height_mm integer DEFAULT NULL::integer, p_depth_mm integer DEFAULT NULL::integer, p_variant character varying DEFAULT NULL::character varying, p_price_source character varying DEFAULT NULL::character varying, p_unit_price_override numeric DEFAULT NULL::numeric, p_notes text DEFAULT NULL::text, p_price_sign smallint DEFAULT 1)
 RETURNS bigint
 LANGUAGE plpgsql
AS $function$
DECLARE
 v_price calc.attachment_price%ROWTYPE;
 v_selection_id BIGINT;
 v_attachment_text TEXT;
BEGIN
 IF p_quote_id IS NULL OR btrim(p_quote_id) = '' THEN
 RAISE EXCEPTION 'quote_id is required';
 END IF;
 IF p_model_code IS NULL AND p_item_name IS NULL THEN
 RAISE EXCEPTION 'model_code or item_name is required';
 END IF;
 IF p_quantity IS NULL OR p_quantity < 0 THEN
 RAISE EXCEPTION 'quantity must be non-negative';
 END IF;
 IF p_price_sign NOT IN (-1, 1) THEN
 RAISE EXCEPTION 'price_sign must be 1 or -1';
 END IF;

 v_attachment_text := COALESCE(p_item_name, '') || ' ' || COALESCE(p_model_code, '');
 IF p_price_sign = -1
 AND (position('安装板' IN v_attachment_text) = 0 OR position('安装板单发' IN v_attachment_text) > 0) THEN
 RAISE EXCEPTION 'negative price_sign is allowed only for an installation board';
 END IF;

 SELECT ap.*
 INTO v_price
 FROM calc.attachment_price ap
 WHERE ap.is_active = TRUE
 AND (p_model_code IS NULL OR ap.model_code = p_model_code OR ap.model_code IS NULL OR ap.model_code = '所有型号')
 AND (p_item_name IS NULL OR ap.item_name = p_item_name)
 AND (p_width_mm IS NULL OR ap.width_mm = p_width_mm)
 AND (p_height_mm IS NULL OR ap.height_mm = p_height_mm)
 AND (p_depth_mm IS NULL OR ap.depth_mm = p_depth_mm)
 AND (p_variant IS NULL OR ap.variant = p_variant OR ap.variant IS NULL)
 AND (p_price_source IS NULL OR ap.price_source = p_price_source)
 ORDER BY
 CASE WHEN ap.model_code = p_model_code THEN 0 ELSE 1 END,
 CASE WHEN ap.item_name = p_item_name THEN 0 ELSE 1 END,
 ap.attachment_price_id DESC
 LIMIT 1;

 IF NOT FOUND THEN
 RAISE EXCEPTION 'attachment price not found: model=%, item=%, variant=%, source=%',
 p_model_code, p_item_name, p_variant, p_price_source;
 END IF;

 INSERT INTO calc.attachment_selection (
 quote_id, product_code, model_code, attachment_price_id,
 item_name, variant, price_source, quantity, unit_price,
 price_text, cost_method, notes, price_sign
 )
 VALUES (
 p_quote_id, p_product_code, v_price.model_code, v_price.attachment_price_id,
 v_price.item_name, v_price.variant, v_price.price_source, p_quantity,
 COALESCE(p_unit_price_override, v_price.price), v_price.price_text,
 'experience', p_notes, p_price_sign
 )
 RETURNING attachment_selection_id INTO v_selection_id;

 RETURN v_selection_id;
END;
$function$
